/* Keeps course search separate from scoring and device-local round storage. */
let courseLookupTimer,courseLookupAbort,courseLookupSequence=0,courseLookupItems=[],courseLookupIndex=-1,courseLookupSelected=null,courseImportSource=null,courseCatalog=[],courseLookupLoad;
function loadCourseCatalog(){if(!courseLookupLoad)courseLookupLoad=fetch('course-catalog.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>courseCatalog=d.courses||[]).catch(()=>{courseLookupLoad=null;return[]});return courseLookupLoad}
function initialiseCourseLookup(existing){clearTimeout(courseLookupTimer);courseLookupAbort?.abort();courseLookupSequence++;courseLookupItems=[];courseLookupIndex=-1;courseLookupSelected=null;courseImportSource=existing?.source||null;$('#modal').onclose=()=>{clearTimeout(courseLookupTimer);courseLookupAbort?.abort();courseLookupSequence++};loadCourseCatalog();}
function courseLookupInput(value){courseImportSource=null;courseLookupSelected=null;$('#courseImportPanel').innerHTML='';clearTimeout(courseLookupTimer);courseLookupAbort?.abort();let sequence=++courseLookupSequence;const q=value.trim();if(q.length<3){$('#courseSuggestions').innerHTML='';$('#cname').setAttribute('aria-expanded','false');$('#courseLookupStatus').textContent='Type at least 3 letters to search online, then choose a course and tee set.';return}courseLookupTimer=setTimeout(()=>runCourseLookup(q,sequence),300)}
function courseSearchCurrent(sequence){return sequence===courseLookupSequence&&$('#modal').open&&!!$('#courseSuggestions')}
function showCourseSuggestions(items){courseLookupItems=items.slice(0,10);courseLookupIndex=-1;$('#cname').removeAttribute('aria-activedescendant');$('#cname').setAttribute('aria-expanded',items.length?'true':'false');$('#courseSuggestions').innerHTML=courseLookupItems.map((c,i)=>`<button id="course-option-${i}" class="course-option" type="button" role="option" aria-selected="false" onclick="chooseCourseResult(${i})"><span class="search-course-symbol">⌕</span><span><strong>${esc(c.name)}</strong><small>${esc(c.location||'Location not supplied')} · ${c.provider==='catalog'?'Saved web scorecard':'Online directory'}</small></span><span>↗</span></button>`).join('')}
async function runCourseLookup(q,sequence){await loadCourseCatalog();if(!courseSearchCurrent(sequence))return;const key=CourseLookup.normal(q),local=courseCatalog.filter(c=>CourseLookup.normal(c.name+' '+(c.aliases||[]).join(' ')).includes(key));showCourseSuggestions(local);$('#courseLookupStatus').textContent='Searching the online directory…';courseLookupAbort=new AbortController();try{const remote=await CourseLookup.search(q,courseLookupAbort.signal);if(!courseSearchCurrent(sequence))return;const names=new Set(local.map(c=>CourseLookup.normal(c.name)));showCourseSuggestions([...local,...remote.filter(c=>!names.has(CourseLookup.normal(c.name)))]);$('#courseLookupStatus').innerHTML=`${courseLookupItems.length?'Choose a course below. Scorecard availability varies.':'No matching course found. Try a longer name or enter the scorecard manually.'} <a href="https://opengolfapi.org/attribution" target="_blank" rel="noopener">Directory: OpenGolfAPI / OSM · ODbL</a>`}catch(e){if(!courseSearchCurrent(sequence))return;$('#courseLookupStatus').textContent=local.length?'Showing saved web scorecards. Online search could not connect.':'Online search could not connect. Check your connection or enter a scorecard manually.'}}
function courseLookupKey(event){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();$('#courseSuggestions').innerHTML='';$('#cname').setAttribute('aria-expanded','false');return}if(!courseLookupItems.length||$('#cname').getAttribute('aria-expanded')!=='true')return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();courseLookupIndex=(courseLookupIndex+(event.key==='ArrowDown'?1:-1)+courseLookupItems.length)%courseLookupItems.length;document.querySelectorAll('.course-option').forEach((el,i)=>el.setAttribute('aria-selected',i===courseLookupIndex?'true':'false'));$('#cname').setAttribute('aria-activedescendant','course-option-'+courseLookupIndex);$('#course-option-'+courseLookupIndex)?.scrollIntoView({block:'nearest'})}else if(event.key==='Enter'){event.preventDefault();chooseCourseResult(courseLookupIndex>=0?courseLookupIndex:0)}}
async function chooseCourseResult(index){const choice=courseLookupItems[index];if(!choice)return;clearTimeout(courseLookupTimer);courseLookupAbort?.abort();const sequence=++courseLookupSequence;$('#courseSuggestions').innerHTML='';$('#cname').setAttribute('aria-expanded','false');$('#cname').removeAttribute('aria-activedescendant');$('#cname').value=choice.name;$('#courseLookupStatus').textContent='Loading available tees and scorecards…';courseLookupAbort=new AbortController();try{const course=choice.provider==='catalog'?JSON.parse(JSON.stringify(choice)):await CourseLookup.detail(choice.id,courseLookupAbort.signal);if(!courseSearchCurrent(sequence))return;courseLookupSelected=course;$('#clocation').value=course.location||'';const current=$('#ctee').value;let match=course.tees.findIndex(t=>t.name===current);if(match<0)match=0;
 $('#courseImportPanel').innerHTML=`<div class="course-import"><div class="eyebrow">COURSE FOUND ONLINE</div><strong>${esc(course.name)}</strong><p class="sub">${esc(course.location)}</p>${course.tees.length?`<label for="onlineTee">Choose tee set / rating category</label><select id="onlineTee" onchange="applyOnlineTee(Number(this.value))">${course.tees.map((t,i)=>`<option value="${i}" ${i===match?'selected':''}>${esc(t.name)}${t.holes.length?' · '+t.holes.length+' holes':''}</option>`).join('')}</select><div id="courseImportSummary"></div>`:'<p class="note">This course is listed, but its hole-by-hole scorecard is not available in the directory. Enter the tee set and scorecard manually.</p>'}<p class="sub">${esc(course.notes||'Please check the scorecard before saving.')}</p><p class="sub">Source: <a href="${esc(CourseLookup.validUrl(course.sourceUrl)||'https://opengolfapi.org')}" target="_blank" rel="noopener">${esc(course.sourceLabel)} ↗</a></p></div>`;
 $('#courseLookupStatus').textContent=course.tees.length?'Choose your tees, review the filled scorecard, then save.':'Course name found. Complete the remaining fields manually.';if(course.tees.length)applyOnlineTee(match);else{courseImportSource=null;$('#ctee').value='';$('#crating').value='';$('#cslope').value='';drawImportedHoles(Array.from({length:18},()=>({par:null,distance:null,si:null})));}
}catch(e){if(!courseSearchCurrent(sequence))return;$('#courseLookupStatus').textContent='Could not load this scorecard. Try another course or enter details manually.'}}
function drawImportedHoles(holes){$('#choles').value=String(holes.length);$('#courseHoleFields').innerHTML=`<table class="course-holes"><thead><tr><th>HOLE</th><th>PAR</th><th>DISTANCE (m)</th><th>STROKE INDEX</th></tr></thead><tbody>${holes.map((h,i)=>`<tr><td>${i+1}</td><td><input aria-label="Hole ${i+1} par" data-cpar="${i}" type="number" min="3" max="6" required value="${h.par??''}" placeholder="—"></td><td><input aria-label="Hole ${i+1} distance" data-cdistance="${i}" type="number" min="0" max="1000" required value="${h.distance??''}" placeholder="—"></td><td><input aria-label="Hole ${i+1} stroke index" data-csi="${i}" type="number" min="1" max="${holes.length}" required value="${h.si??''}" placeholder="—"></td></tr>`).join('')}</tbody></table>`}
function applyOnlineTee(index){const course=courseLookupSelected,tee=course?.tees[index];if(!tee)return;const issues=CourseLookup.issues(tee);$('#ctee').value=tee.name;$('#crating').value=tee.rating??'';$('#cslope').value=tee.slope??'';if([9,18].includes(tee.holes.length))drawImportedHoles(tee.holes);else drawImportedHoles(Array.from({length:18},()=>({par:null,distance:null,si:null})));courseImportSource={provider:course.provider,externalId:course.id,teeId:tee.id,url:CourseLookup.validUrl(course.sourceUrl),label:course.sourceLabel,retrievedAt:course.retrievedAt||new Date().toISOString(),notes:course.notes||'',license:course.provider==='opengolfapi'?'ODbL-1.0':null};$('#courseImportSummary').innerHTML=issues.length?`<p class="note"><b>Some details need completing.</b> ${issues.map(esc).join(' ')} Unknown values have been left blank.</p>`:`<div class="import-success">✓ ${tee.holes.length} holes filled · Par ${sum(tee.holes.map(h=>h.par))} · ${sum(tee.holes.map(h=>h.distance))} m</div>`;if(tee.rating==null||tee.slope==null)$('#courseImportSummary').innerHTML+='<p class="sub">Course/slope rating not supplied for this tee set. Add it from today’s card if needed.</p>';}
